window.kbPageData["views/entry/k-f69764c84da266b9"] = {"key":"entry/k-f69764c84da266b9","state":{"route":"entry/k-f69764c84da266b9"},"node":{"id":"k-f69764c84da266b9","mode":"k","title":"违法解除劳动合同的救济","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["违法解除劳动合同的救济为继续履行或依法支付赔偿金"],"qs":["江苏 2023 B类 行测#12"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"用人单位违法解除或者终止劳动合同，劳动者要求继续履行且合同仍能履行的，用人单位应当继续履行。劳动者不要求继续履行或者合同已经不能继续履行的，用人单位应当按法定经济补偿标准的二倍支付赔偿金。","review":{"definition":"用人单位违法解除或者终止劳动合同，劳动者要求继续履行且合同仍能履行的，用人单位应当继续履行。劳动者不要求继续履行或者合同已经不能继续履行的，用人单位应当按法定经济补偿标准的二倍支付赔偿金。","explanation":"连续两年考核末位只表明王某的相对排名，公司仍须证明其不能胜任工作。题中仅凭末位和拒绝调岗解除合同，缺乏法定依据。所查公开题本网络版的B项同样写作“经济补偿金”，参考答案也列B。B项关于违法解除的判断成立，但金钱救济写错了，依法应为赔偿金。","references":[{"source":"web-322a25ea8bce7f43","location":"第四十八条、第八十七条","quote":"经济补偿标准的二倍"},{"source":"web-8a55d7f2bba5768f","location":"选项B及参考答案栏","quote":"王某有权请求支付经济补偿金"}],"evidence":"公司解除劳动合同违法，王某有权请求支付经济补偿金","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2023 B类 行测#12":{"paper":"江苏 2023 B类 行测","n":12,"mod":"常识判断","src":["22262c34d18cd68fbee4.pdf",2],"asrc":["b08f2713d73015eac675.pdf",5],"card":"8e66ce0a4bb20d071224c459","links":[{"id":"k-f69764c84da266b9","role":"直接考查","why":"劳动者要求继续履行时应继续履行，劳动者无此要求或合同已无法继续履行时适用赔偿金规则。"}]}},"terms":{},"references":{"web-322a25ea8bce7f43":{"name":"《中华人民共和国劳动合同法》","url":"https://www.samr.gov.cn/zw/zfxxgk/fdzdgknr/bgt/art/2023/art_0abfdd261c03417b949df19d869add8d.html-0"},"web-8a55d7f2bba5768f":{"name":"星光公考公开题本","url":"https://www.xingguanggongkao.com/Wb/quesView/id/47145.html"}},"topics":[],"units":{"k-f69764c84da266b9":[["江苏 2023 B类 行测#12"]]}};
